import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const defaultRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export const RELEASE_INFO_PATH = 'apps/web/src/app/release/release-info.generated.ts';

const literal = (value) =>
  JSON.stringify(value).replace(/[\u2028\u2029]/g, (c) => '\\u' + c.charCodeAt(0).toString(16));

export function renderReleaseInfo(version, changelog) {
  return [
    '// Generated by scripts/generate-release-info.mjs. Do not edit.',
    `export const APP_VERSION: string = ${literal(version)};`,
    `export const APP_CHANGELOG: string = ${literal(changelog)};`,
    '',
  ].join('\n');
}

export function generateReleaseInfo(root = defaultRoot) {
  const { version } = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
  if (typeof version !== 'string' || version === '') {
    throw new Error('Root package.json has no version.');
  }
  const changelog = readFileSync(join(root, 'CHANGELOG.md'), 'utf8');
  const target = join(root, RELEASE_INFO_PATH);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, renderReleaseInfo(version, changelog));
  return target;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    generateReleaseInfo();
  } catch (error) {
    console.error(`generate-release-info: ${error.message}`);
    process.exitCode = 1;
  }
}
